<template>
  <div class="tp-page">
    <t-card class="tp-card">
      <template #title>
        <div class="tp-head">
          <span class="tp-title">问题标签</span>
          <span class="tp-sub">
            共 {{ tags.length }} 个标签。每个标签下面列出它的全部叫法——
            搜索任一种说法都能找到同一批题；标签列表展示的是通用名，
            具体到题目展示的是那道题自己设置的那个叫法。
          </span>
        </div>
      </template>

      <!-- 筛选区：标签多起来之后，靠眼睛在几百张卡片里找一个是不可用的 -->
      <div class="tp-toolbar">
        <t-input
          v-model="keyword"
          class="tp-filter"
          placeholder="筛选标签（通用名或任一叫法）"
          clearable
        />
        <t-checkbox v-model="onlyPinned">只看置顶</t-checkbox>
        <span class="tp-muted">
          <template v-if="isFiltering">显示 {{ filtered.length }} / {{ tags.length }}</template>
          <template v-else>共 {{ tags.length }} 个</template>
        </span>
        <t-button v-if="isFiltering" size="small" variant="text" @click="resetFilter">
          清除筛选
        </t-button>
      </div>

      <div v-if="loading" class="tp-hint">加载中…</div>
      <div v-else-if="loadFailed" class="tp-hint tp-hint-error">标签加载失败，请刷新重试</div>
      <div v-else-if="tags.length === 0" class="tp-hint">暂无标签</div>
      <div v-else-if="filtered.length === 0" class="tp-hint">
        没有匹配「{{ keyword.trim() }}」的标签
        <t-button size="small" variant="text" @click="resetFilter">清除筛选</t-button>
      </div>
      <div v-else class="tp-grid">
        <div
          v-for="tag in filtered"
          :key="tag.id"
          class="tp-item"
          :class="{ 'tp-item-active': isActive(tag) }"
          @click="goTag(tag)"
        >
          <div class="tp-item-head">
            <span class="tp-name">{{ tag.name }}</span>
            <span v-if="tag.pinned" class="tp-pin">置顶</span>
            <span class="tp-usage">{{ tag.usage_count ?? 0 }}</span>
          </div>
          <div v-if="aliasNames(tag).length" class="tp-aliases">
            <span v-for="alias in aliasNames(tag)" :key="alias" class="tp-alias">{{ alias }}</span>
          </div>
          <div v-else class="tp-no-alias">无其他叫法</div>
        </div>
      </div>
    </t-card>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { GetProblemTagList } from "@/apis/problem.ts";

// 本地接口而不是复用 ProblemTag：members 是后端按需填充的字段（gorm:"-"），
// 只在这个页面用得到，不值得为它改动共享类型。
interface TagCall {
  id: number;
  name: string;
}

interface TagItem {
  id: number;
  name: string;
  // 概念级挂题数（同概念的叫法共享一个值），用来判断这个词是不是冷门
  usage_count?: number;
  pinned?: boolean;
  // 同一概念的全部叫法（含通用名自己）
  members?: TagCall[];
}

const tags = ref<TagItem[]>([]);
const loading = ref(false);
const loadFailed = ref(false);
const keyword = ref("");
const onlyPinned = ref(false);
const router = useRouter();
const route = useRoute();

const isFiltering = computed(() => keyword.value.trim() !== "" || onlyPinned.value);

// 全部叫法（不含通用名自己）：通用名已经作为标题显示了，再列一遍是重复信息
const aliasNames = (tag: TagItem) =>
  (tag.members ?? []).filter((m) => m.id !== tag.id).map((m) => m.name);

// 前端筛选而不是再打一次后端：这个页面本来就一次性取全量（-1），
// 本地过滤是即时的，也让「筛」这件事不产生网络往返。
// 匹配范围是**全部叫法**：用户记得的是「DSU」而不是「并查集」，
// 只匹配通用名会让他觉得「明明有这个标签却搜不到」。
const filtered = computed(() => {
  const kw = keyword.value.trim().toLowerCase();
  return tags.value.filter((tag) => {
    if (onlyPinned.value && !tag.pinned) {
      return false;
    }
    if (!kw) {
      return true;
    }
    if (tag.name.toLowerCase().includes(kw)) {
      return true;
    }
    return (tag.members ?? []).some((m) => m.name.toLowerCase().includes(kw));
  });
});

const resetFilter = () => {
  keyword.value = "";
  onlyPinned.value = false;
};

// 从题目列表点标签过来时带上 ?tag=xxx，高亮当前筛的那个标签。
// 比对范围含全部叫法：用户从别名进的列表页，回到这里也该看到高亮。
const isActive = (tag: TagItem) => {
  const active = ((route.query.tag as string) || "").trim();
  if (!active) {
    return false;
  }
  if (tag.name === active) {
    return true;
  }
  return (tag.members ?? []).some((m) => m.name === active);
};

const fetchTags = async () => {
  loading.value = true;
  loadFailed.value = false;
  try {
    // -1 = 全量。这个页面就是要展示全部标签，不做渲染裁剪
    const res = await GetProblemTagList(-1);
    if (res.code === 0) {
      tags.value = (res.data?.list ?? []) as TagItem[];
    } else {
      loadFailed.value = true;
    }
  } catch (err) {
    // 必须吞掉异常：没有 catch 的话请求一旦失败，整个组件的渲染会被打断，
    // 页面看起来就是「标签一个都没显示」而没有任何提示
    console.error(err);
    loadFailed.value = true;
  } finally {
    loading.value = false;
  }
};

// 点标签 = 回题目列表按它筛题。传通用名而不是被点的那个叫法：检索会按概念展开，
// 两者效果一致，而通用名在 URL 里更可读。
const goTag = (tag: TagItem) => {
  router.push({ name: "problem-list", query: { tag: tag.name } });
};

onMounted(fetchTags);
</script>

